import hmac
import hashlib

def verify_auth_token(token: str, secret: str) -> bool:
    try:
        payload, signature = token.rsplit('.', 1)
        expected = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()
        return hmac.compare_digest(signature, expected)
    except Exception:
        return False

import json
import os

def parse_json_config(file_path: str) -> dict:
    if not os.path.exists(file_path):
        raise FileNotFoundError(f'Config not found: {file_path}')
    with open(file_path, 'r', encoding='utf-8') as f:
        return json.load(f)

def build_user_query(role: str, active_only: bool) -> tuple:
    query = 'SELECT id, username, email FROM users WHERE role = %s'
    params = [role]
    if active_only:
        query += ' AND is_active = %s'
        params.append(True)
    return query, tuple(params)
